            min_sum = 0
            max_sum = 0
        else:
            min_sum = k * (k - 1) // 2
            max_sum = k * (2 * N - k - 1) // 2

        start_k = k * X + D * min_sum
        end_k = k * X + D * max_sum

        min_val = min(start_k, end_k)
        max_val = max(start_k, end_k)

        residue = start_k % d
        residue_intervals[residue].append([min_val, max_val])

    total = 0

    for intervals in residue_intervals.values():
        intervals.sort()
        merged = []
        for interval in intervals:
            if not merged:
                merged.append(interval)
            else:
                last = merged[-1]
                if interval[0] <= last[1] + 1:
                    merged[-1][1] = max(last[1], interval[1])
                else:
                    merged.append(interval)
        for a, b in merged:
            count = (b - a) // d + 1
            total += count

    print(total)

