from collections import defaultdict

def main():
    input = sys.stdin.read
    N, X, D = map(int, input().split())

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    groups = defaultdict(list)

    for K in range(0, N + 1):
        if K == 0:
            a_K = 0
            b_K = 0
        else:
            a_K = (K - 1) * K // 2
            b_K = K * (2 * N - K - 1) // 2

        L = X * K + D * a_K
        R = X * K + D * b_K
        min_val = min(L, R)
        max_val = max(L, R)

        r = (X * K) % D

        A = min_val - r
        B = max_val - r

        if D > 0:
            k_min = (A + D - 1) // D
            k_max = B // D
        else:
            k_min = - (B // (-D))
            k_max = A // D

        if k_max >= k_min:
            groups[r].append((k_min, k_max))

    total = 0
    for r in groups:
        ranges = groups[r]
        ranges.sort()
        merged = []
        for start, end in ranges:
            if not merged:
                merged.append((start, end))
            else:
                last_start, last_end = merged[-1]
                if start <= last_end + 1:
                    new_start = last_start
                    new_end = max(last_end, end)
                    merged[-1] = (new_start, new_end)
                else:
                    merged.append((start, end))
        for start, end in merged:
            total += end - start + 1

    print(total)

if __name__ == "__main__":
