import sys

def factorize(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 1
    if x > 1:
        factors[x] = 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for prime, exp in factors.items():
        temp = []
        for d in divisors:
            current = d
            for e in range(exp + 1):
                temp.append(current * (prime ** e))
        divisors = temp
    return divisors

def is_valid(M, K):
    if M < K:
        return M == 1
    if M % K == 0:
        return is_valid(M // K, K)
    else:
        return (M % K == 1)

def main():
    N = int(sys.stdin.readline())

    # Compute count1: number of divisors of N-1 >= 2
    x = N - 1
    if x == 0:
        count1 = 0
    else:
        factors = factorize(x)
        divisors = get_divisors(factors)
        count1 = len([d for d in divisors if d >= 2])

    # Compute count2: number of divisors of N >= 2 that satisfy the condition
    factors = factorize(N)
    divisors = get_divisors(factors)
    count2 = 0
    for K in divisors:
        if K < 2:
            continue
        M = N // K
        if is_valid(M, K):
            count2 += 1

    print(count1 + count2)

if __name__ == "__main__":
    main()
