import sys

def main():
    H, W = map(int, sys.stdin.readline().split())
    A = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]
    B = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]

    max_diff = (H + W - 1) * 80
    offset = max_diff
    size = 2 * max_diff + 1

    # Initialize dp with False
    dp = [[[False] * size for _ in range(W)] for _ in range(H)]

    # Initialize the starting cell (0,0)
    d_current = A[0][0] - B[0][0]
    val1 = d_current
    val2 = -d_current
    for val in [val1, val2]:
        index = val + offset
        if 0 <= index < size:
            dp[0][0][index] = True

    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue
            current_d = A[i][j] - B[i][j]
            current_dp = [False] * size
            # Check top cell (i-1, j)
            if i > 0:
                for k in range(size):
                    if dp[i-1][j][k]:
                        val_prev = k - offset
                        new_val1 = val_prev + current_d
                        new_val2 = val_prev - current_d
                        index1 = new_val1 + offset
                        index2 = new_val2 + offset
                        if 0 <= index1 < size:
                            current_dp[index1] = True
                        if 0 <= index2 < size:
                            current_dp[index2] = True
            # Check left cell (i, j-1)
            if j > 0:
                for k in range(size):
                    if dp[i][j-1][k]:
                        val_prev = k - offset
                        new_val1 = val_prev + current_d
                        new_val2 = val_prev - current_d
                        index1 = new_val1 + offset
                        index2 = new_val2 + offset
                        if 0 <= index1 < size:
                            current_dp[index1] = True
                        if 0 <= index2 < size:
                            current_dp[index2] = True
            dp[i][j] = current_dp

    min_abs = float('inf')
    for k in range(size):
        if dp[H-1][W-1][k]:
            val = k - offset
            abs_val = abs(val)
            if abs_val < min_abs:
                min_abs = abs_val
    print(min_abs)

if __name__ == "__main__":
    main()
