    A = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]
    B = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]

    max_sum = (H + W - 1) * 80
    size = 2 * max_sum + 1

    dp = [[[False] * size for _ in range(W)] for _ in range(H)]

    # Initialize starting cell (0, 0)
    diff1 = A[0][0] - B[0][0]
    diff2 = B[0][0] - A[0][0]
    index1 = diff1 + max_sum
    index2 = diff2 + max_sum
    dp[0][0][index1] = True
    dp[0][0][index2] = True

    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue
            current_dp = [False] * size
            # Check top cell (i-1, j)
            if i > 0:
                for k in range(size):
                    if dp[i-1][j][k]:
                        s = k - max_sum
                        new_diff1 = s + (A[i][j] - B[i][j])
                        new_diff2 = s + (B[i][j] - A[i][j])
                        index1 = new_diff1 + max_sum
                        index2 = new_diff2 + max_sum
                        if 0 <= index1 < size:
                            current_dp[index1] = True
                        if 0 <= index2 < size:
                            current_dp[index2] = True
            # Check left cell (i, j-1)
            if j > 0:
                for k in range(size):
                    if dp[i][j-1][k]:
                        s = k - max_sum
                        new_diff1 = s + (A[i][j] - B[i][j])
                        new_diff2 = s + (B[i][j] - A[i][j])
                        index1 = new_diff1 + max_sum
                        index2 = new_diff2 + max_sum
                        if 0 <= index1 < size:
                            current_dp[index1] = True
                        if 0 <= index2 < size:
                            current_dp[index2] = True
            dp[i][j] = current_dp

    min_abs = float('inf')
    for k in range(size):
        if dp[H-1][W-1][k]:
            s = k - max_sum
            abs_s = abs(s)
            if abs_s < min_abs:
                min_abs = abs_s
    print(min_abs)

