def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    H = list(map(int, input[2:2+N]))

    # Initialize previous state: previous[k] is a dictionary of {value: min_sum}
    previous = [{} for _ in range(K+1)]
    previous[0][0] = 0

    for i in range(1, N+1):
        current = [{} for _ in range(K+1)]
        for k in range(K+1):
            for v_prev in previous[k]:
                sum_prev = previous[k][v_prev]
                # Case 1: do not modify column i
                new_v = H[i-1]
                new_sum = sum_prev + max(0, new_v - v_prev)
                if new_v in current[k]:
                    if new_sum < current[k][new_v]:
                        current[k][new_v] = new_sum
                else:
                    current[k][new_v] = new_sum
                # Case 2: modify column i
                if k + 1 <= K:
                    new_v_mod = v_prev
                    new_sum_mod = sum_prev
                    if new_v_mod in current[k+1]:
                        if new_sum_mod < current[k+1][new_v_mod]:
                            current[k+1][new_v_mod] = new_sum_mod
                    else:
                        current[k+1][new_v_mod] = new_sum_mod
        previous = current

    min_total = float('inf')
    for k in range(K+1):
        if previous[k]:
            min_total = min(min_total, min(previous[k].values()))
