        b = int(input[idx]); idx += 1
        c = int(input[idx]); idx += 1
        packages.append((a, b, c))

    delta_list = [(a * M_b - b * M_a, c) for a, b, c in packages]
    mid = N // 2
    first_part = delta_list[:mid]
    second_part = delta_list[mid:]

    def generate_subsets(elements):
        n = len(elements)
        subsets = {}
        for mask in range(1 << n):
            sum_val = 0
            cost = 0
            count = 0
            for i in range(n):
                if mask & (1 << i):
                    sum_val += elements[i][0]
                    cost += elements[i][1]
                    count += 1
            if count > 0:
                if sum_val in subsets:
                    if cost < subsets[sum_val]:
                        subsets[sum_val] = cost
                else:
                    subsets[sum_val] = cost
        return subsets

    first_dict = generate_subsets(first_part)
    second_dict = generate_subsets(second_part)

    min_cost = float('inf')
    for key in first_dict:
        target = -key
        if target in second_dict:
            total = first_dict[key] + second_dict[target]
            if total < min_cost:
                min_cost = total

    if 0 in first_dict:
        if first_dict[0] < min_cost:
            min_cost = first_dict[0]
    if 0 in second_dict:
        if second_dict[0] < min_cost:
            min_cost = second_dict[0]

    print(-1 if min_cost == float('inf') else min_cost)

