import sys

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def count_exponent(n, p):
    count = 0
    power = p
    while power <= n:
        count += n // power
        power *= p
    return count

def main():
    N = int(sys.stdin.readline())
    primes = sieve(N)
    exponents = []
    for p in primes:
        e = count_exponent(N, p)
        exponents.append(e)

    count1 = 0
    for e in exponents:
        if e >= 74:
            count1 += 1

    a2 = 0
    b2 = 0
    for e in exponents:
        if e >= 24:
            a2 += 1
        if e >= 2:
            b2 += 1
    count2 = a2 * (b2 - 1)

    a3 = 0
    b3 = 0
    for e in exponents:
        if e >= 14:
            a3 += 1
        if e >= 4:
            b3 += 1
    count3 = a3 * (b3 - 1)

    a4 = 0
    b4 = 0
    for e in exponents:
        if e >= 4:
            a4 += 1
        if e >= 2:
            b4 += 1
    if a4 >= 2 and b4 >= 2:
        count4 = (a4 * (a4 - 1) // 2) * (b4 - 2)
    else:
