import sys
from itertools import permutations

def main():
    N = int(sys.stdin.readline())
    # Generate primes up to N using sieve of Eratosthenes
    primes = []
    is_prime = [True] * (N + 1)
    for i in range(2, N + 1):
        if is_prime[i]:
            primes.append(i)
            for j in range(i * i, N + 1, i):
                is_prime[j] = False
    # Compute exponents for each prime in N!
    exponents = []
    for p in primes:
        exp = 0
        power = p
        while power <= N:
            exp += N // power
            power *= p
        exponents.append(exp)
    # Generate all possible combinations of factors that multiply to 75
    divisors = [1, 3, 5, 15, 25, 75]
    result_factors = []
    def generate(n, current):
        if n == 1:
            result_factors.append(current.copy())
            return
        for d in divisors:
            if n % d == 0:
                current.append(d)
                generate(n // d, current)
                current.pop()
    generate(75, [])
    # Calculate total number of valid Shichi-Go numbers
    total = 0
    for combo in result_factors:
        # Generate all unique permutations of the combo
        unique_perms = set(permutations(combo))
        for perm in unique_perms:
            available = exponents.copy()
            ways = 1
            for factor in perm:
                required = factor - 1
                count = 0
                for i in range(len(available)):
                    if available[i] >= required:
                        count += 1
                if count == 0:
                    break
                ways *= count
                # Remove one eligible prime
                for i in range(len(available)):
                    if available[i] >= required:
                        del available[i]
                        break
            total += ways
    print(total)

if __name__ == "__main__":
    main()
